const fmtSaved=t=>`${t.orders||0} pedidos · ${t.receipts||0} repasses${t.ledger?` · ${t.ledger} contas`:''}`;
// O servidor guarda o andamento; a página só acompanha. Fechar a página não interrompe: o agendamento do servidor continua a cada 2 minutos.
async function runSync(id){const [from,to]=syncRange();integ.busy[id]=true;integ.progress[id]='Iniciando…';render();let r={},rounds=0;
 try{do{r=await callFn('integrations',{action:'sync',provider:id,from,to});integ.progress[id]=`${r.busy?'Em andamento no servidor… ':r.next?'Continuando… ':''}${fmtSaved(r.saved||{})} · pode fechar a página`;if(page==='integracoes')render();if(r.busy)await new Promise(ok=>setTimeout(ok,15000))}while(r.next&&++rounds<400);
  audit('Sincronização '+PROVIDERS.find(p=>p.id===id).label,`${from} a ${to}: ${fmtSaved(r.saved||{})}.`);
  integ.progress[id]=`Concluído: ${fmtSaved(r.saved||{})}${r.notes?.length?' · '+r.notes.join(' '):''}`;
 }catch(e){integ.progress[id]='Falhou: '+e.message+' · o servidor tenta de novo sozinho';toast(e.message)}
 finally{integ.busy[id]=false;await Cloud.reload();await loadIntegrations()}}

// ───────── Conciliação em lote (correspondências exatas) ─────────
function exactPairs(){const out=[];for(const o of scoped()){if(status(o)==='Conciliado'||db.closures[o.date.slice(0,7)])continue;const rs=db.receipts.filter(r=>!r.linkedOrder&&r.orderId===o.id&&r.platform===o.platform&&!db.closures[r.date.slice(0,7)]);if(!rs.length)continue;const sum=round(rs.reduce((a,r)=>a+r.amount,0)),open=round(net(o)-paid(o));if(sum>0&&Math.abs(sum-open)<.01)for(const r of rs)out.push({receipt:r.id,order:o.id,amount:r.amount,reason:rs.length>1?`${rs.length} liberações somam o saldo`:'Pedido idêntico e valor exato'})}return out}
// Aplica vínculos já revisados. Usado pela conciliação em lote e pelas propostas do assistente.
window.applyLinks=function(pairs,origin){let ok=0,skipped=[];for(const p of pairs){const r=db.receipts.find(x=>x.id===p.receipt),o=db.orders.find(x=>x.id===p.order);if(!r||!o){skipped.push(`${p.receipt}: não encontrado`);continue}if(r.linkedOrder){skipped.push(`${r.id}: já vinculada`);continue}if(db.closures[o.date.slice(0,7)]||db.closures[r.date.slice(0,7)]){skipped.push(`${r.id}: competência fechada`);continue}r.linkedOrder=o.id;ok++;db.audit.unshift({id:uid(),time:new Date().toISOString(),action:'Vínculo confirmado',detail:`${r.id} → ${o.id} · ${money(r.amount)} · ${origin}${p.reason?' · '+p.reason:''}`})}paymentIndex=null;save();render();return {ok,skipped}};
let batch=[];
function batchModal(pairs,title,origin){batch=pairs;modal(title,pairs.length?`<div class="notice">Revise antes de confirmar. Cada vínculo fica registrado na auditoria e pode ser desfeito no pedido.</div><div class="tablewrap" style="max-height:48vh"><table><thead><tr><th><input type="checkbox" class="check" id="batchAll" checked aria-label="Selecionar todos"></th><th>Liberação</th><th>Pedido</th><th class="num">Valor</th><th>Critério</th></tr></thead><tbody>${pairs.map((p,i)=>`<tr><td><input type="checkbox" class="check" data-batch="${i}" checked></td><td>${esc(p.receipt)}</td><td>${esc(p.order)}</td><td class="num">${money(p.amount??db.receipts.find(r=>r.id===p.receipt)?.amount??0)}</td><td class="caption">${esc(p.reason||'')}</td></tr>`).join('')}</tbody></table></div><div class="modalfoot"><button data-action="close">Cancelar</button><button class="primary" data-fx-batch-confirm="${esc(origin)}">${icon('check')} Confirmar selecionados</button></div>`:'<div class="empty">Nenhuma correspondência exata pendente nesta competência.</div>')}
window.batchModal=batchModal;
